import{THREE as t}from"./js_TP/tpb.min.js";const f={name:"bar3d",computeSize({data:e,unitM:o,barWidthM:r=10,barDepthM:n=10,gapM:s=2}){const a=Math.max(0,...e.map(h=>h.value)),c=e.length;return{width:c*r+(c-1)*s,depth:n,height:a*o}},build({data:e,unitM:o,barWidthM:r=10,barDepthM:n=10,gapM:s=2,strokeColor:a}){const c=new t.Group;let h=0;for(const u of e){const i=Math.max(.1,u.value*o),l=new t.BoxGeometry(r,i,n);l.translate(0,i/2,0);const w=new t.MeshStandardMaterial({color:u.color??"#3388ff",roughness:.5}),d=new t.Mesh(l,w);if(d.position.x=h+r/2,a){const M=new t.MeshBasicMaterial({color:a,wireframe:!0}),m=new t.Mesh(l,M);m.scale.set(1.01,1.01,1.01),d.add(m)}c.add(d),h+=r+s}return c}},g={name:"pie3d",computeSize({data:e,unitM:o}){const r=e.reduce((s,a)=>s+Math.max(0,a.value),0),n=Math.sqrt(r)*o;return{width:n*2,depth:n*2,height:n*.5}},build({data:e,unitM:o,strokeColor:r}){const n=new t.Group,s=e.reduce((u,i)=>u+Math.max(0,i.value),0);if(s<=0)return n;const a=Math.sqrt(s)*o,c=a*.5;let h=0;for(const u of e){const i=Math.max(0,u.value)/s*Math.PI*2;if(i<=0)continue;const l=new t.CylinderGeometry(a,a,c,32,1,!1,h,i);l.translate(0,c/2,0);const w=new t.MeshStandardMaterial({color:u.color??"#3388ff",roughness:.5}),d=new t.Mesh(l,w);if(r){const M=new t.MeshBasicMaterial({color:r,wireframe:!0}),m=new t.Mesh(l,M);m.scale.set(1.01,1.01,1.01),d.add(m)}n.add(d),h+=i}return n}},p={bar3d:f,pie3d:g};function D(e){const o=p[e];if(!o)throw new Error(`Diagram3D: unknown type "${e}". Registered: ${Object.keys(p).join(", ")}`);return o}export{p as DIAGRAM3D_TYPES,f as bar3D,D as getDiagram3DType,g as pie3D};
